const fs = require('fs');
const path = require('path');

const readmePath = path.join(__dirname, 'README.md');
const indexPath = path.join(__dirname, 'INDEX.md');

const content = fs.readFileSync(readmePath, 'utf8');
const lines = content.split('\n');
const matches = [];
let inFence = false;

for (const line of lines) {
  if (line.startsWith('```')) {
    inFence = !inFence;
    continue;
  }
  if (inFence) continue;
  if (line.startsWith('#')) {
    matches.push(line);
  }
}

fs.writeFileSync(indexPath, matches.join('\n') + '\n');
console.log('Wrote', matches.length, 'heading(s) to INDEX.md');

